import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadFeaturedData(){const e=readFileSync(resolve(__dirname,"../../featured-coins-section/featured-data.js"),"utf-8");return new Function(e+"\nreturn { FEATURED_COINS_DATA };")()}describe("Featured Coins Section — Data Tests",()=>{let e;beforeAll(()=>{e=loadFeaturedData()}),describe("FEATURED_COINS_DATA array",()=>{it("contains at least 4 featured coins with required fields",()=>{expect(Array.isArray(e.FEATURED_COINS_DATA)).toBe(!0),expect(e.FEATURED_COINS_DATA.length).toBeGreaterThanOrEqual(4),e.FEATURED_COINS_DATA.forEach(e=>{expect(e.id).toBeDefined(),expect(e.name).toBeDefined(),expect(e.period).toBeDefined(),expect(e.significance).toBeDefined(),expect(e.fact).toBeDefined(),expect(e.explorerUrl).toBeDefined()})}),it("includes iconic Shivaji Hon and Jahangir Leo Mohur",()=>{const t=e.FEATURED_COINS_DATA.find(e=>"shivaji-hon"===e.id);expect(t).toBeDefined(),expect(t.period).toContain("1674");const i=e.FEATURED_COINS_DATA.find(e=>"jahangir-leo-mohur"===e.id);expect(i).toBeDefined(),expect(i.metal).toBe("Gold")})})});